package main

import (
    "fmt"
    "os"
    "strings"
    "github.com/google/blueprint"
)

var packageContext = blueprint.NewPackageContext("corpuscheck")
var commandRule = packageContext.StaticRule("genrule", blueprint.RuleParams{Command: "$cmd"}, "cmd")

type genrule struct {
    props struct {
        Name string
        Out []string
        Cmd string
    }
}

func (rule *genrule) Name() string { return rule.props.Name }

func (rule *genrule) GenerateBuildActions(context blueprint.ModuleContext) {
    command := strings.ReplaceAll(rule.props.Cmd, "$(out)", strings.Join(rule.props.Out, " "))
    command = strings.ReplaceAll(command, "\n", "\\n")
    context.Build(packageContext, blueprint.BuildParams{
        Rule: commandRule,
        Outputs: rule.props.Out,
        Args: map[string]string{"cmd": command},

    })
}

func fail(errors []error) {
    if len(errors) == 0 { return }
    for _, problem := range errors { fmt.Fprintln(os.Stderr, problem) }
    os.Exit(1)
}

func main() {
    context := blueprint.NewContext()
    context.RegisterModuleType("genrule", func() (blueprint.Module, []interface{}) {
        rule := new(genrule)
        return rule, []interface{}{ &rule.props }
    })
    _, errors := context.ParseFileList(".", []string{os.Args[1]}, nil)
    fail(errors)
    _, errors = context.ResolveDependencies(nil)
    fail(errors)
    _, errors = context.PrepareBuildActions(nil)
    fail(errors)
    manifest, err := os.Create("build.ninja")
    if err != nil { panic(err) }
    if err := context.WriteBuildFile(manifest); err != nil { panic(err) }
    if err := manifest.Close(); err != nil { panic(err) }
}
